"""Use the shared article chrome for compact player references."""
from html import escape

from build_guides import page_open, page_close


def article_open(title, page, lead, sections, builder):
    opening = page_open(title, lead, page, 'guide-page reference-page', 'guide-body',
                        'Skip to the article', 'PLAYER REFERENCE')
    opening = opening.replace(
        'Generated by tools/build_guides.py from data/guides.json. Do not edit by hand.',
        f'Generated by tools/{builder}. Do not edit by hand.')
    return (opening + '<nav class="wiki-breadcrumb" aria-label="Breadcrumb">'
            '<a href="index.html">Home</a><span aria-hidden="true">/</span>'
            f'<span aria-current="page">{escape(title)}</span></nav>'
            '<section class="intro" aria-labelledby="title"><div class="intro-row">'
            f'<h1 id="title">{escape(title)}</h1><p>{escape(lead)}</p></div></section>'
            '<article class="wiki-article" aria-labelledby="title">'
            '<details class="wiki-contents" open><summary>Contents</summary>'
            '<nav aria-label="On this page"><ol>' + ''.join(
                f'<li><a href="#{key}">{escape(label)}</a></li>' for key, label in sections) +
            '</ol></nav></details><div id="guide-body">')


def article_close():
    return '</div></article>' + page_close()
